using System;

class Program
{
    static void Main(string[] args)
    {
        double number = 7.75;
        string result = ConvertDoubleToString(number, 5);
        Console.WriteLine(result);
    }

    static string ConvertDoubleToString(double number, int precision)
    {
        long wholePart = (long)number;
        double fractionalPart = number - wholePart;

        string result = wholePart.ToString();

        if (fractionalPart != 0)
        {
            result += ".";
            for (int i = 0; i < precision; i++)
            {
                fractionalPart *= 10;
                int digit = (int)fractionalPart;
                result += digit.ToString();
                fractionalPart -= digit;
            }
        }

        return result;
    }
}
